// Load the authenticated, authorized server snapshot before starting the app.
(async()=>{const screen=document.createElement('div');screen.id='boot-screen';screen.innerHTML='<div class="boot-card"><span class="boot-logo">✳ Task Extreme</span><h2>Preparando tu espacio</h2><p>Verificando tu cuenta y permisos…</p></div>';document.body.append(screen);document.body.classList.add('booting');const nativeSet=Storage.prototype.setItem;window.NexoCloud={nativeSet,revision:0,userId:null,paused:false};try{const response=await fetch('/api/state',{cache:'no-store'}),result=await response.json();if(!response.ok)throw Object.assign(Error(result.error),{status:response.status});let local=null;try{local=JSON.parse(localStorage.getItem('nexo-legacy-backup-v1')||(!localStorage.getItem('nexo-cloud-established')?localStorage.getItem('nexo-v1'):'null'))}catch{}if(local&&!localStorage.getItem('nexo-legacy-backup-v1'))nativeSet.call(localStorage,'nexo-legacy-backup-v1',JSON.stringify(local));nativeSet.call(localStorage,'nexo-cloud-established','1');window.NexoCloud.legacy=local;window.NexoCloud.importStateDone=localStorage.getItem('nexo-import-state-done')==='1';window.NexoCloud.importAvailable=(result.revision===0||result.state.importWindowOpen||window.NexoCloud.importStateDone)&&!localStorage.getItem('nexo-cloud-imported-'+result.userId)&&result.state.users.find(u=>u.id===result.userId)?.role==='principal'&&!!local?.tasks?.length;window.NexoCloud.revision=result.revision;window.NexoCloud.userId=result.userId;result.state.previewUserId=result.userId;nativeSet.call(localStorage,'nexo-v1',JSON.stringify(result.state));const scripts=['team-client-policy.js','app.js','updates.js','workspaces.js','companies.js','management.js','profile-dashboard.js','subtasks.js','inline-list.js','custom-columns.js','status-config.js','cloud-client.js','personal-home.js','monday-core.js','monday-import.js','audit-ui.js','role-home.js','team-admin.js','global-search.js','auth-client.js'];for(const file of scripts)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/'+file;script.onload=resolve;script.onerror=()=>reject(Error('No se pudo cargar '+file));document.body.append(script)});screen.remove();document.body.classList.remove('booting')}catch(error){if(error.status===428){location.assign('/cambiar-contrasena');return}screen.innerHTML='<div class="boot-card"><span class="boot-logo">✳ Task Extreme</span><h2>No pudimos abrir tu espacio</h2><p id="boot-error"></p><a href="/login" target="_top">Iniciar sesión</a><button onclick="location.reload()">Reintentar</button><a href="/salir" target="_top">Cambiar cuenta</a></div>';screen.querySelector('#boot-error').textContent=error.message}})();
